function portfolioInsights(projects){const total=projects.length,featured=projects.filter(project=>project.featured).length,withoutVisual=projects.find(project=>!project.cover_image_data&&!project.cover_image&&!project.gallery_images?.length),incomplete=projects.find(project=>caseStoryItems(project).some(([, ,done])=>!done)),recommendations=[];if(total&&!featured)recommendations.push({title:'Выберите ключевые работы',description:'Избранные кейсы попадут в вашу витрину. Можно начать с одной самой сильной работы.',view:true});if(withoutVisual)recommendations.push({title:'Добавьте визуальное доказательство',description:`У проекта «${withoutVisual.title}» ещё нет обложки или галереи.`,project:withoutVisual});if(incomplete){const [key,label]=caseStoryItems(incomplete).find(([, ,done])=>!done);if(key!=='visuals'&&recommendations.length<3){const titles={context:'Опишите задачу и контекст',role:'Расскажите о своей роли',solution:'Объясните выбранное решение',process:'Покажите ход работы',outcome:'Сформулируйте результат'};recommendations.push({title:titles[key]||`Дополните блок «${label}»`,description:`Следующая подсказка в кейсе «${incomplete.title}». Добавляйте только то, что можете подтвердить.`,project:incomplete})}}const untagged=projects.find(project=>!project.tags?.length);if(untagged&&recommendations.length<3)recommendations.push({title:'Добавьте точные теги',description:`Теги помогут быстрее найти «${untagged.title}» среди других работ.`,project:untagged});if(!total)recommendations.push({title:'Создайте первый кейс',description:'Начните с одной работы: название и короткое описание уже помогут зафиксировать основу.',create:true});const statusRows=STATUSES.map(status=>({status,count:projects.filter(project=>project.status===status).length})),technologies=new Map();for(const project of projects)for(const technology of project.technologies||[])technologies.set(technology,(technologies.get(technology)||0)+1);const topTechnologies=[...technologies].sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0],'ru')).slice(0,4);return `<section class="portfolio-insights" aria-label="Подсказки и состав портфолио"><article class="insight-card insight-next"><div class="insight-heading"><div><span class="eyebrow">БЕЗ ОЦЕНКИ КАЧЕСТВА</span><h2>Что можно улучшить</h2></div><span class="insight-count">${recommendations.length?`${recommendations.length} ${countLabel(recommendations.length,['подсказка','подсказки','подсказок'])}`:'готово'}</span></div><p class="insight-intro">Это добровольные идеи, а не обязательные требования. Вы сами решаете, что уместно для каждого проекта.</p>${recommendations.length?`<ol class="insight-list">${recommendations.slice(0,3).map((item,index)=>`<li><span class="insight-number" aria-hidden="true">0${index+1}</span><div class="insight-item-copy"><b>${esc(item.title)}</b><p>${esc(item.description)}</p>${item.project?`<button class="text-button insight-action" data-insight-edit="${item.project.id}">Открыть кейс ↗</button>`:item.view?'<button class="text-button insight-action" data-view="projects">Выбрать проекты ↗</button>':'<button class="text-button insight-action" data-action="new-project">＋ Новый проект</button>'}</div></li>`).join('')}</ol>`:'<div class="insight-complete"><span aria-hidden="true">✓</span><div><b>Основные поля заполнены</b><p>Проверьте, что выбранные детали действительно помогают рассказать вашу историю. Оставить кейс лаконичным — тоже хороший выбор.</p></div></div>'}</article><article class="insight-card insight-mix"><div class="insight-heading"><div><span class="eyebrow">СОСТАВ РАБОТ</span><h2>Портфолио сейчас</h2></div><span class="insight-count">${total} ${plural(total)}</span></div><div class="status-distribution" role="list" aria-label="Проекты по статусу">${statusRows.map(row=>{const percent=total?Math.round(row.count/total*100):0;return `<div class="status-row" role="listitem" aria-label="${esc(row.status)}: ${row.count} ${plural(row.count)}"><span>${esc(row.status)}</span><div class="status-track" aria-hidden="true"><i style="width:${percent}%"></i></div><b>${row.count}</b></div>`}).join('')}</div><div class="insight-technologies"><b>Чаще всего используются</b>${topTechnologies.length?`<ul>${topTechnologies.map(([name,count])=>`<li><span>${esc(name)}</span><b>${count}</b></li>`).join('')}</ul>`:'<p>Добавьте технологии в карточки, чтобы увидеть распределение.</p>'}</div></article></section>`}
