function deleteSelectedProjects(){const ids=model.projects.filter(project=>selectedProjectIds.has(project.id)).map(project=>project.id);if(!ids.length)return;const label=countLabel(ids.length,['проект','проекта','проектов']);if(confirm(`Удалить ${label}? Их можно восстановить в течение 7 секунд.`))removeProjectsWithUndo(ids,`Удалено ${label}. Можно отменить в течение 7 секунд.`)}
function openSavedFilterDialog(){pendingFilterView=normalizeFilterSnapshot(filters());const existing=readSavedFilterViews().find(item=>sameFilterSnapshot(item.filters,pendingFilterView));$('#saved-filter-name').value=existing?.name||'';$('#saved-filter-form-error').textContent='';openDialog($('#saved-filter-dialog'),$('#saved-filter-name'),document.activeElement)}
function persistSavedFilterView(){const name=$('#saved-filter-name').value.trim(),error=$('#saved-filter-form-error');if(!name){error.textContent='Введите название подборки.';$('#saved-filter-name').focus();return}if(name.length>40){error.textContent='Название должно быть не длиннее 40 символов.';return}const views=readSavedFilterViews(),same=views.find(item=>sameFilterSnapshot(item.filters,pendingFilterView)),nameCollision=views.find(item=>item.name.toLocaleLowerCase('ru')===name.toLocaleLowerCase('ru')&&item.id!==same?.id);if(nameCollision){error.textContent=`Название «${nameCollision.name}» уже используется. Выберите другое.`;$('#saved-filter-name').focus();return}if(!same&&views.length>=MAX_SAVED_FILTER_VIEWS){error.textContent=`Можно сохранить не больше ${MAX_SAVED_FILTER_VIEWS} подборок.`;return}const next=same?views.map(item=>item.id===same.id?{...item,name,filters:pendingFilterView}:item):[...views,{id:globalThis.crypto?.randomUUID?.()||`view-${Date.now()}-${Math.random().toString(36).slice(2)}`,name,filters:pendingFilterView}];try{localStorage.setItem(SAVED_FILTER_VIEWS_KEY,JSON.stringify(next))}catch(failure){error.textContent=`Не удалось сохранить: ${failure.message}`;return}const updated=Boolean(same);pendingFilterView=null;$('#saved-filter-dialog').close();render();$('#saved-filter-view')?.focus();toast(updated?'Подборка обновлена.':'Подборка сохранена на этом устройстве.')}
function applySavedFilterView(id){const saved=readSavedFilterViews().find(item=>item.id===id);if(!saved){render();return}const snapshot=saved.filters,tag=$('#filter-tag');for(const [selector,value] of [['#search-input',snapshot.query],['#filter-type',snapshot.type],['#filter-status',snapshot.status],['#sort-projects',snapshot.sort]])$(selector).value=value;$('#filter-featured').checked=snapshot.featuredOnly;if(tag){if(snapshot.tag!=='Все теги'&&![...tag.options].some(option=>option.value===snapshot.tag))tag.add(new Option(snapshot.tag,snapshot.tag));tag.value=snapshot.tag}view='projects';render();announceProjectResults();$('#saved-filter-view')?.focus();toast(`Подборка «${saved.name}» применена.`)}
function deleteSavedFilterView(){const id=$('#saved-filter-view')?.value,views=readSavedFilterViews(),index=views.findIndex(item=>item.id===id),removed=views[index];if(!removed)return;views.splice(index,1);try{localStorage.setItem(SAVED_FILTER_VIEWS_KEY,JSON.stringify(views));render();$('#saved-filter-view')?.focus();toast(`Подборка «${removed.name}» удалена.`,false,{label:'Отменить',onDismiss:()=>requestAnimationFrame(()=>{if(document.activeElement===document.body||!document.activeElement?.isConnected)$('#saved-filter-view')?.focus({preventScroll:true})}),run:async()=>{const restored=readSavedFilterViews();if(restored.some(item=>item.id===removed.id))throw new Error('Такая подборка уже существует.');restored.splice(Math.min(index,restored.length),0,removed);localStorage.setItem(SAVED_FILTER_VIEWS_KEY,JSON.stringify(restored));render();$('#saved-filter-view')?.focus();toast(`Подборка «${removed.name}» восстановлена.`)}})}catch(error){toast(`Не удалось удалить: ${error.message}`,true)}}
function projects(){const f=filters(),rows=filterProjects(model.projects,f);return `${head('КАТАЛОГ РАБОТ','Все проекты','Ищите, сортируйте и управляйте своим портфолио.',`<button class="button button-accent" data-action="new-project">＋ Новый проект</button>`)}<section class="filter-panel"><label class="search-field"><span class="search-icon" aria-hidden="true"></span><input id="search-input" type="search" placeholder="Название, технология, тег, роль…" value="${esc(f.query)}" aria-label="Поиск проектов"><kbd>Ctrl/⌘ K</kbd></label><select id="filter-type" aria-label="Тип"><option>Все типы</option>${TYPES.map(x=>`<option ${f.type===x?'selected':''}>${esc(x)}</option>`).join('')}</select><select id="filter-status" aria-label="Статус"><option>Все статусы</option>${STATUSES.map(x=>`<option ${f.status===x?'selected':''}>${esc(x)}</option>`).join('')}</select><select id="filter-tag" aria-label="Тег"><option>Все теги</option>${filterTagOptions(f.tag)}</select><select id="sort-projects" aria-label="Сортировка проектов"><option value="featured" ${f.sort==='featured'?'selected':''}>Избранные</option><option value="order" ${f.sort==='order'?'selected':''}>Мой порядок</option><option value="newest" ${f.sort==='newest'?'selected':''}>Новые</option><option value="oldest" ${f.sort==='oldest'?'selected':''}>Старые</option><option value="title" ${f.sort==='title'?'selected':''}>А → Я</option></select><label class="check-filter"><input id="filter-featured" type="checkbox" ${f.featuredOnly?'checked':''}> Избранное</label></section>${savedFilterToolbar(f)}${bulkSelectionToolbar(rows)}<div class="results-line"><div class="result-summary"><b>${rows.length} ${plural(rows.length)}</b><span>${rows.length===model.projects.length?"Показаны все работы":"Фильтры применены"}</span></div><div class="results-actions"><label class="select-visible-control"><input id="select-visible-projects" type="checkbox" aria-label="Выбрать показанные проекты"><span>Выбрать показанные</span></label><div class="view-toggle" role="group" aria-label="Вид проектов"><button type="button" data-layout-choice="cards" aria-pressed="${projectLayout==="cards"?"true":"false"}">Карточки</button><button type="button" data-layout-choice="list" aria-pressed="${projectLayout==="list"?"true":"false"}">Список</button></div><button class="text-button" id="reset-filters">Сбросить фильтры</button></div></div>${rows.length?`<div class="project-grid${projectLayout==="list"?" project-list":""}">${rows.map(project=>card(project,true)).join("")}</div>`:`<div class="empty-state"><span>⌕</span><b>${model.projects.length?'Ничего не найдено':'Добавьте первый проект'}</b><p>${model.projects.length?'Измените запрос или сбросьте фильтры.':'Ваше портфолио начнётся с одной хорошей истории.'}</p><button class="button button-quiet" id="reset-empty">${model.projects.length?'Сбросить фильтры':'＋ Новый проект'}</button></div>`}`}
function showcase(){
  const featured=filterProjects(model.projects,{sort:'featured'}).filter(project=>project.featured);
  const developer=model.developer;
  const intro=developer.introduction?esc(developer.introduction).replaceAll('\n','<br>'):'Избранные кейсы из вашего локального портфолио.';
  const contacts=[[developer.include_email&&developer.email?`mailto:${developer.email}`:'','Email'],[developer.include_website&&developer.website_url?developer.website_url:'','Личный сайт'],[developer.include_github&&developer.github_url?developer.github_url:'','GitHub']]
    .filter(([href])=>href).map(([href,label])=>`<a href="${esc(href)}"${href.startsWith('mailto:')?'':' target="_blank" rel="noopener noreferrer"'}>${label} ↗</a>`).join('');
  const actions=`<button class="button button-quiet" data-action="export-md">Экспорт Markdown</button><button class="button button-quiet" data-action="preview-static">Предпросмотр HTML</button><button class="button button-accent" data-action="export-static">↓ Скачать готовую витрину</button>`;
  const themePicker=`<label class="showcase-theme-picker"><span>Стиль HTML-страницы</span><select id="showcase-theme" aria-describedby="showcase-theme-help"><option value="editorial" ${showcaseTheme==='editorial'?'selected':''}>Редакционный</option><option value="night" ${showcaseTheme==='night'?'selected':''}>Ночной</option><option value="gallery" ${showcaseTheme==='gallery'?'selected':''}>Галерея</option></select><small id="showcase-theme-help">Меняет только файл витрины, не карточки проектов.</small></label>`;
  const cards=featured.length?`<div class="project-grid showcase-grid">${featured.map(card).join('')}</div>`:'<div class="empty-state"><img class="empty-state-art" src="./assets/illustrations/featured-empty-folio.webp" alt="" aria-hidden="true"><b>Витрина пока не заполнена</b><p>Отметьте проект как избранный, чтобы показать его здесь.</p><button class="button button-quiet" data-view="projects">Выбрать проекты</button></div>';
  return `${head('ПРЕДПРОСМОТР ВИТРИНЫ','Работы, которыми<br>хочется поделиться.','Проверьте избранные кейсы и автономную страницу перед скачиванием.',actions)}${themePicker}<div class="showcase-banner"><span class="eyebrow">${esc(developer.specialization).toUpperCase()}</span><h2>${esc(developer.full_name)}</h2><p>${intro}</p>${contacts?`<nav class="profile-contact-links" aria-label="Контакты автора">${contacts}</nav>`:''}<span class="showcase-count">${esc(caseCountLabel(featured.length).toUpperCase())}</span></div>${cards}`;
}
function settings(){const d=model.developer;return `${head('ПРОСТРАНСТВО','Настройки и данные','Ваши проекты сохранены только в этом браузере.',`<span class="local-lock">Локально на этом устройстве</span>`)}<div class="settings-grid"><section class="settings-card"><span class="eyebrow">ПРОФИЛЬ</span><h2>Как вас представить?</h2><p>Добавьте короткое вступление и выберите контакты, которые попадут в предпросмотр и статический экспорт.</p><form id="profile-form" class="settings-form"><label class="field"><span>Имя</span><input name="full_name" required maxlength="90" value="${esc(d.full_name)}"></label><label class="field"><span>Специализация</span><input name="specialization" required maxlength="90" value="${esc(d.specialization)}"></label><label class="field"><span>Вступление</span><textarea name="introduction" maxlength="800" rows="4" placeholder="Коротко о вашем подходе и интересах">${esc(d.introduction)}</textarea><small class="field-hint">До 800 символов. Текст появится во вступлении витрины.</small></label><label class="field"><span>Email</span><input name="email" type="email" maxlength="254" autocomplete="email" value="${esc(d.email)}"></label><label class="profile-toggle"><input type="checkbox" name="include_email" ${d.include_email?'checked':''}><span>Показывать email в портфолио</span></label><label class="field"><span>Личный сайт</span><input name="website_url" type="url" inputmode="url" maxlength="300" placeholder="https://..." value="${esc(d.website_url)}"></label><label class="profile-toggle"><input type="checkbox" name="include_website" ${d.include_website?'checked':''}><span>Показывать личный сайт в портфолио</span></label><label class="field"><span>GitHub</span><input name="github_url" type="url" inputmode="url" maxlength="300" placeholder="https://github.com/..." value="${esc(d.github_url)}"></label><label class="profile-toggle"><input type="checkbox" name="include_github" ${d.include_github?'checked':''}><span>Показывать GitHub в портфолио</span></label><p class="profile-form-error" id="profile-form-error" role="alert"></p><button class="button button-dark">Сохранить профиль</button></form></section><section class="settings-card"><span class="eyebrow">РЕЗЕРВНАЯ КОПИЯ</span><h2>Ваши данные — под контролем</h2><p>JSON переносит проекты между настольной и браузерной версиями.</p><div class="data-actions"><button class="button button-accent" data-action="export-json">↓ Скачать резервную копию</button><button class="button button-quiet" data-action="import-json">↑ Импортировать JSON</button><button class="button button-quiet" data-action="export-csv">Экспорт CSV</button></div><div class="data-info"><b>Сохранение на устройстве</b><span>IndexedDB этого браузера. Для другого устройства экспортируйте JSON и импортируйте файл.</span></div></section><section class="settings-card danger-card"><span class="eyebrow">УПРАВЛЕНИЕ ДАННЫМИ</span><h2>Очистить рабочее пространство</h2><p>Все проекты будут удалены из этого браузера. Это действие нельзя отменить.</p><button class="button button-danger" data-action="clear-all">Удалить все проекты</button></section><section class="settings-card about-card"><span class="eyebrow">О ПРОЕКТЕ</span><h2>folio® <span class="version-chip">LOCAL · PWA</span></h2><p>Локальное портфолио с офлайн-доступом. Автоматической облачной синхронизации нет.</p><div class="offline-line"><i></i><span id="offline-text">${navigator.onLine?'Готово к работе без сети':'Офлайн — данные доступны'}</span></div><button class="text-button install-button" data-action="install" hidden>Установить приложение</button></section></div>`}
function render(){selectedProjectIds=new Set([...selectedProjectIds].filter(id=>model.projects.some(project=>project.id===id)));main.innerHTML=({dashboard,projects,showcase,settings})[view]();$('#breadcrumb-current').textContent=({dashboard:'Обзор',projects:'Мои проекты',showcase:'Витрина',settings:'Настройки и данные'})[view];document.querySelectorAll('[data-view]').forEach(x=>{const current=x.dataset.view===view;x.classList.toggle('active',current);if(x.matches('.nav-item,.mobile-nav-item')){if(current)x.setAttribute('aria-current','page');else x.removeAttribute('aria-current')}});$('#theme-toggle').setAttribute('aria-pressed',String(document.documentElement.dataset.theme==='dark'));$('#nav-count').textContent=model.projects.length;$('#avatar-small').textContent=(model.developer.full_name||'Д')[0].toLocaleUpperCase('ru');$('#profile-small-name').textContent=model.developer.full_name;$('#profile-small-role').textContent=model.developer.specialization;if(installPrompt&&$('.install-button'))$('.install-button').hidden=false;const selectVisible=$('#select-visible-projects');if(selectVisible){const visible=filterProjects(model.projects,filters()),selected=visible.filter(project=>selectedProjectIds.has(project.id)).length;selectVisible.checked=visible.length>0&&selected===visible.length;selectVisible.indeterminate=selected>0&&selected<visible.length;selectVisible.disabled=!visible.length}}
function updateCaseGuide(){const form=$('#project-form'),bar=$('#case-guide-progress');if(!form||!bar)return;const value=name=>String(form.elements.namedItem(name)?.value||'').trim(),items=caseStoryItems({context:value('context'),role:value('role'),solution:value('solution'),process:value('process'),outcome:value('outcome'),metrics:value('metrics'),cover_image_data:value('cover_image_data'),cover_image:editingCoverPath,gallery_images:editingGallery});const completed=items.filter(([, ,done])=>done).length,total=items.length;bar.setAttribute('aria-valuenow',String(completed));bar.setAttribute('aria-valuetext',`${completed} из ${total} дополнительных блоков`);bar.querySelector('.case-guide-progress-fill').style.width=`${completed/total*100}%`;$('#case-guide-count').textContent=`${completed} из ${total}`;const next=items.find(([, ,done])=>!done);$('#case-guide-next').textContent=next?completed===0?'Начните с задачи и своей роли. Заполняйте только то, что можете подтвердить.':`Следующий блок — «${next[1]}». Заполняйте его, если вам есть что показать.`:'Все подсказки учтены. Проверьте, что описание и изображения можно показывать.';for(const [key,,done] of items){const row=document.querySelector(`[data-case-guide="${key}"]`);if(row){row.dataset.complete=String(done);const marker=row.querySelector('span');if(marker)marker.textContent=done?'✓':'○'}}}
function renderCoverPreview(src=''){const host=$('#cover-preview');host.innerHTML=src?`<img src="${esc(src)}" alt="" decoding="async">`:'<span>Добавьте иллюстрацию проекта</span>';$('#remove-cover').hidden=!src;updateCaseGuide()}
function renderGalleryEditor(){const host=$('#gallery-editor');if(!host)return;host.innerHTML=editingGallery.length?editingGallery.map((image,index)=>{const [x='50',y='50']=image.position.split(' ').map(value=>value.replace('%',''));return `<article class="gallery-item"><img src="${esc(image.image_data)}" alt="${esc(image.alt||'Предпросмотр дополнительного изображения')}" style="object-position:${esc(image.position)}"><div class="gallery-item-fields"><label>Описание изображения<input data-gallery-alt="${index}" maxlength="180" value="${esc(image.alt)}" placeholder="Опишите, что показано"></label><fieldset><legend>Кадрирование</legend><label>По горизонтали <input type="range" min="0" max="100" value="${x}" data-gallery-x="${index}" aria-label="Кадрирование по горизонтали, изображение ${index+1}"></label><label>По вертикали <input type="range" min="0" max="100" value="${y}" data-gallery-y="${index}" aria-label="Кадрирование по вертикали, изображение ${index+1}"></label></fieldset><div class="gallery-item-actions"><span>Деталь ${index+1} из ${GALLERY_MAX_IMAGES}</span><button type="button" class="text-button" data-gallery-up="${index}" aria-label="Переместить изображение ${index+1} выше" ${index?'':'disabled'}>↑</button><button type="button" class="text-button" data-gallery-down="${index}" aria-label="Переместить изображение ${index+1} ниже" ${index<editingGallery.length-1?'':'disabled'}>↓</button><button type="button" class="text-button" data-gallery-remove="${index}">Удалить</button></div></div></article>`}).join(''):'<p class="gallery-empty">Дополнительные изображения помогут показать экраны и детали проекта.</p>';$('#gallery-images-data').value=JSON.stringify(editingGallery);$('#gallery-files').disabled=editingGallery.length>=GALLERY_MAX_IMAGES;$('.gallery-file-label').setAttribute('aria-disabled',String(editingGallery.length>=GALLERY_MAX_IMAGES));updateCaseGuide()}
async function encodeGalleryImage(file,maxChars=GALLERY_MAX_IMAGE_DATA_CHARS){if(!['image/png','image/jpeg','image/webp'].includes(file.type))throw new Error('Выберите PNG, JPEG или WebP.');if(file.size>10*1024*1024)throw new Error('Исходное изображение должно быть меньше 10 МиБ.');const source=URL.createObjectURL(file);try{const image=new Image();image.src=source;await image.decode();if(image.naturalWidth*image.naturalHeight>24000000)throw new Error('Уменьшите разрешение изображения до 24 мегапикселей.');const scale=Math.min(1,1600/Math.max(image.naturalWidth,image.naturalHeight)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.naturalWidth*scale));canvas.height=Math.max(1,Math.round(image.naturalHeight*scale));canvas.getContext('2d',{alpha:false}).drawImage(image,0,0,canvas.width,canvas.height);for(const quality of [.84,.76,.68,.6]){const data=canvas.toDataURL('image/webp',quality);if(data.length<=Math.min(GALLERY_MAX_IMAGE_DATA_CHARS,maxChars))return data}throw new Error('Сжатая картинка всё ещё слишком велика. Выберите изображение попроще.')}finally{URL.revokeObjectURL(source)}}
async function clearProjectDraft(){clearTimeout(draftSaveTimer);await draftWriteQueue.catch(()=>{});await draftStore.put(null)}
function scheduleProjectDraftSave(){clearTimeout(draftSaveTimer);const status=$('#project-draft-status');if(status)status.textContent='Сохраняю черновик на этом устройстве…';draftSaveTimer=setTimeout(()=>{const form=$('#project-form'),draft={version:1,editing_id:editingId,cover_image:editingCoverPath,gallery_images:editingGallery,values:Object.fromEntries(new FormData(form)),featured:form.elements.featured.checked,updated_at:new Date().toISOString()};draftWriteQueue=draftWriteQueue.catch(()=>{}).then(()=>draftStore.put(draft)).then(()=>{const current=$('#project-draft-status');if(current)current.textContent='Черновик сохранён на этом устройстве.'}).catch(()=>{const current=$('#project-draft-status');if(current)current.textContent='Не удалось сохранить черновик. Оставьте форму открытой и попробуйте ещё раз.'})},350)}
async function openProject(p=null,restoreTarget=null){const requestedId=p?.id??null;let draft=null;try{draft=await draftStore.get()}catch{}if(draft){if(draft.editing_id===requestedId){if(!confirm('Найден несохранённый черновик этой карточки. Восстановить его?'))await clearProjectDraft();else if(!p)p={type:TYPES[0],status:'В разработке',created_at:today(),page_count:1,technologies:[],gallery_images:[]}}else{if(!confirm('Есть несохранённый черновик другой карточки. Удалить его и продолжить?'))return;await clearProjectDraft();draft=null}}editingId=requestedId;const form=$('#project-form');form.reset();$('#form-error').textContent='';$('#project-draft-status').textContent='Несохранённые изменения автоматически сохраняются на этом устройстве.';$('#project-dialog-title').textContent=p?'Редактировать проект':'Новый проект';p=p||{type:TYPES[0],status:'В разработке',created_at:today(),page_count:1,technologies:[],gallery_images:[]};editingCoverPath=draft?.cover_image||p.cover_image||'';editingGallery=(draft?.gallery_images||p.gallery_images||[]).map(image=>({...image}));form.elements.cover_image_data.value=p.cover_image_data||'';renderCoverPreview(p.cover_image_data||p.cover_image||'');renderGalleryEditor();for(const [key,val] of Object.entries({type:p.type,status:p.status,title:p.title||'',description:p.description||'',created_at:p.created_at,demo_url:p.demo_url||'',technologies:(p.technologies||[]).join(', '),role:p.role||'',outcome:p.outcome||'',context:p.context||'',solution:p.solution||'',process:p.process||'',metrics:p.metrics||'',tags:(p.tags||[]).join(', '),page_count:p.page_count||1,repository_url:p.repository_url||'',backend_stack:p.backend_stack||'',featured:p.featured||false})){const el=form.elements.namedItem(key);if(el){if(el.type==='checkbox')el.checked=!!val;else el.value=val}}if(draft){for(const [key,val] of Object.entries(draft.values||{})){const el=form.elements.namedItem(key);if(el){if(el.type==='checkbox')el.checked=key==='featured'?draft.featured:!!val;else el.value=val}}if(form.elements.featured)form.elements.featured.checked=!!draft.featured;editingGallery=(draft.gallery_images||[]).map(image=>({...image}));renderGalleryEditor();renderCoverPreview(form.elements.cover_image_data.value||editingCoverPath);$('#project-draft-status').textContent=`Черновик восстановлен · ${new Date(draft.updated_at).toLocaleString('ru-RU')}`}renderCaseTags();$('#case-tag-status').textContent='';$('#case-tag-entry').removeAttribute('aria-invalid');updateCaseGuide();toggleFields();openDialog($('#project-dialog'),form.elements.title,restoreTarget||document.activeElement)}
function toggleFields(){const landing=$('#form-type').value===TYPES[0];document.querySelectorAll('.landing-field').forEach(x=>x.hidden=!landing);document.querySelectorAll('.webapp-field').forEach(x=>x.hidden=landing);$('#project-form').elements.page_count.required=landing}
function moveAvailability(p,direction){const peers=model.projects.filter(x=>x.featured===p.featured).sort((a,b)=>a.sort_order-b.sort_order||a.id-b.id),index=peers.findIndex(x=>x.id===p.id);return index+direction>=0&&index+direction<peers.length}
