function isPlaceholderUrl(value){if(!value)return false;try{const url=new URL(value),host=url.hostname.toLowerCase(),path=url.pathname.split('/').filter(Boolean);return ['example.com','example.net','example.org'].includes(host)||(host==='github.com'&&path[0]?.toLowerCase()==='example')}catch{return false}}
function detail(id){const p=model.projects.find(x=>x.id===+id);if(!p)return;const links=[p.demo_url,p.repository_url],coverSrc=p.cover_image_data||p.cover_image||(p.type===TYPES[0]?'./assets/covers/portfolio-studio.webp':'./assets/covers/cleaning-crm.webp'),story=[['КОНТЕКСТ ЗАДАЧИ',p.context],['РЕШЕНИЕ',p.solution],['ЭТАПЫ РАБОТЫ',p.process],['МЕТРИКИ РЕЗУЛЬТАТА',p.metrics]].filter(([,value])=>value).map(([label,value])=>`<section class="detail-story"><span class="eyebrow">${label}</span><p>${esc(value).replaceAll('\n','<br>')}</p></section>`).join(''),gallery=(p.gallery_images||[]).map((image,index)=>`<figure class="detail-gallery-item"><img src="${esc(image.image_data)}" alt="${esc(image.alt)}" style="object-position:${esc(image.position)}"${index?' loading="lazy"':''}><figcaption>${esc(image.alt)}</figcaption></figure>`).join('');$('#detail-content').innerHTML=`<div class="detail-hero ${p.type===TYPES[1]?'cover-violet':''}"><button class="icon-button detail-close" data-close-dialog aria-label="Закрыть">×</button><span class="eyebrow">${p.featured?'★ ИЗБРАННЫЙ КЕЙС':'ПРОЕКТ'} · ${esc(p.created_at)}</span><h2 id="detail-title">${esc(p.title)}</h2><p>${esc(p.type)} · ${esc(p.status)}</p><img class="detail-cover-image" src="${esc(coverSrc)}" alt="Иллюстрация проекта: ${esc(p.title)}" decoding="async"><span class="detail-shade" aria-hidden="true"></span></div><div class="detail-body"><div><span class="eyebrow">О ПРОЕКТЕ</span><p>${esc(p.description)}</p></div>${story}${gallery?`<section class="detail-gallery"><span class="eyebrow">В ДЕТАЛЯХ</span><div>${gallery}</div></section>`:''}<div class="detail-two"><div><span class="eyebrow">МОЯ РОЛЬ</span><p>${esc(p.role||'Не указана')}</p></div><div><span class="eyebrow">РЕЗУЛЬТАТ</span><p>${esc(p.outcome||'Не указан')}</p></div></div><div><span class="eyebrow">ТЕХНОЛОГИИ</span><div class="tag-row">${p.technologies.map(t=>`<i>${esc(t)}</i>`).join('')||'Не указаны'}</div></div>${p.tags?.length?`<div><span class="eyebrow">ТЕГИ</span><div class="tag-row user-tag-row">${p.tags.map(t=>`<i>${esc(t)}</i>`).join('')}</div></div>`:''}<div class="detail-links">${p.demo_url&&!isPlaceholderUrl(p.demo_url)?`<a class="button button-accent" href="${esc(p.demo_url)}" target="_blank" rel="noopener noreferrer">Открыть демо ↗</a>`:''}${p.repository_url&&!isPlaceholderUrl(p.repository_url)?`<a class="button button-quiet" href="${esc(p.repository_url)}" target="_blank" rel="noopener noreferrer">Исходный код ↗</a>`:''}${links.some(isPlaceholderUrl)?'<span class="link-placeholder" role="note">Для этого учебного кейса демо-ссылка не добавлена</span>':''}</div><div class="detail-actions"><span class="visually-hidden" id="order-message" aria-live="polite"></span><button class="button button-quiet" data-move="${p.id}" data-direction="-1" aria-label="Поднять ${esc(p.title)} выше" ${moveAvailability(p,-1)?'':'disabled'}>↑ Выше</button><button class="button button-quiet" data-move="${p.id}" data-direction="1" aria-label="Опустить ${esc(p.title)} ниже" ${moveAvailability(p,1)?'':'disabled'}>↓ Ниже</button><button class="button button-quiet" data-duplicate="${p.id}">⧉ Создать копию</button><button class="button button-quiet" data-edit="${p.id}">Изменить</button><button class="text-button" data-delete="${p.id}">Удалить проект</button></div></div>`;openDialog($('#detail-dialog'),$('#detail-content .detail-close'),document.activeElement.matches('[data-detail]')?document.activeElement:document.querySelector(`[data-detail="${p.id}"]`)||document.activeElement)}
function download(name,content,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
async function buildStaticShowcase(){
  const covers={};
  for(const project of model.projects.filter(item=>item.featured)){
    if(project.cover_image_data){covers[project.id]=project.cover_image_data;continue}
    const src=project.cover_image||(project.type===TYPES[0]?'./assets/covers/portfolio-studio.webp':'./assets/covers/cleaning-crm.webp');
    try{
      const response=await fetch(src);if(!response.ok)continue;
      const blob=await response.blob();
      const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result));reader.onerror=()=>reject(reader.error);reader.readAsDataURL(blob)});
      const mime=/\.png$/i.test(src)?'image/png':/\.jpe?g$/i.test(src)?'image/jpeg':'image/webp';
      covers[project.id]=data.replace(/^data:[^;,]+/,`data:${mime}`);
    }catch{}
  }
  return staticShowcaseExport(model,covers,{theme:showcaseTheme});
}
function renderShowcaseExportSummary(){
  const summary=showcaseExportSummary(model),host=$('#showcase-export-summary');
  const imageCount=summary.projects.reduce((total,project)=>total+project.images,0);
  const linkCount=summary.projects.reduce((total,project)=>total+project.links.length,0);
  const contacts=summary.contacts.length?summary.contacts.map(item=>`<li><b>${esc(item.label)}:</b> ${esc(item.value)}</li>`).join(''):'<li>Контактные данные не будут включены.</li>';
  const projects=summary.projects.length?summary.projects.map(project=>`<li><b>${esc(project.title)}</b><span>${countLabel(project.images,['изображение','изображения','изображений'])} · ${project.links.length?`${countLabel(project.links.length,['ссылка','ссылки','ссылок'])}: ${project.links.map(esc).join(' · ')}`:'без внешних ссылок'}</span></li>`).join(''):'<li>Избранных кейсов пока нет — витрина будет пустой.</li>';
  const intro=summary.introduction?`<li><b>Вступление:</b> ${esc(summary.introduction)}</li>`:'<li>Будет показан стандартный текст вступления.</li>';
  host.innerHTML=`<div class="showcase-export-stats"><div><b>${summary.projects.length}</b><span>${esc(caseCountLabel(summary.projects.length))}</span></div><div><b>${imageCount}</b><span>${esc(countLabel(imageCount,['изображение','изображения','изображений']))}</span></div><div><b>${linkCount}</b><span>${esc(countLabel(linkCount,['ссылка на кейс','ссылки на кейсы','ссылок на кейсы']))}</span></div></div><p class="showcase-export-privacy">HTML-файл сохранится на этом устройстве. Если отправить его или разместить в интернете, выбранные кейсы, изображения и контакты станут доступны получателям.</p><details class="showcase-export-details"><summary>Посмотреть точный состав файла</summary><div class="showcase-export-lists"><section><h3>Автор и контакты</h3><ul><li><b>${esc(summary.author)}</b> · ${esc(summary.specialization)}</li>${intro}${contacts}</ul></section><section><h3>Избранные кейсы</h3><ul>${projects}</ul></section></div></details>`;
}
async function previewStaticShowcase(){
  const returnTarget=document.activeElement,dialog=$('#showcase-preview-dialog'),frame=$('#showcase-preview-frame');
  const trigger=main.querySelector('[data-action="preview-static"]');if(trigger){trigger.disabled=true;trigger.setAttribute('aria-busy','true')}
  try{
    pendingShowcaseHtml=await buildStaticShowcase();
    renderShowcaseExportSummary();
    frame.srcdoc=pendingShowcaseHtml;
    openDialog(dialog,$('#showcase-preview-close'),returnTarget);
  }catch(error){toast(`Не удалось подготовить предпросмотр: ${error.message}`,true)}
  finally{if(trigger){trigger.disabled=false;trigger.removeAttribute('aria-busy')}}
}
function exportStaticShowcase(){previewStaticShowcase()}
function renderImportPreview(fileName){const preview=previewPortfolioImport(model.projects,pendingImport.data.projects);$('#import-file-name').textContent=fileName;$('#import-summary').innerHTML=`В файле <b>${preview.incoming}</b> ${plural(preview.incoming)}, в портфолио сейчас <b>${preview.current}</b>. Совпадающих ID: <b>${preview.conflicts.length}</b>. Новых: <b>${preview.additions}</b>.`;const list=$('#import-conflicts');if(preview.conflicts.length){list.innerHTML=`<h3>Совпадения по ID</h3><ul>${preview.conflicts.slice(0,8).map(item=>`<li><b>#${item.id}</b> ${esc(item.currentTitle)} <span aria-hidden="true">→</span> ${esc(item.incomingTitle)}</li>`).join('')}</ul>${preview.conflicts.length>8?`<small>И ещё ${preview.conflicts.length-8} совпадений.</small>`:''}`}else list.innerHTML='<p class="import-clean">Совпадающих ID нет. Все проекты можно добавить без замены существующих.</p>';$('#import-copy').hidden=!preview.conflicts.length;$('#import-keep').textContent=preview.conflicts.length?'Объединить, оставить мои совпадения':'Добавить в портфолио';$('#import-replace').textContent=preview.conflicts.length?'Заменить портфолио целиком':'Заменить портфолио целиком';openDialog($('#import-dialog'),$('#import-dialog [data-close-dialog]'),importDialogOpener||$('#import-file'));importDialogOpener=null}
async function applyPortfolioImport(strategy){if(!pendingImport)return;const incoming=pendingImport.data;if(strategy==='replace'&&model.projects.length)download('folio-before-import.json',JSON.stringify(serializePortfolio(model),null,2),'application/json');if(strategy==='replace'){model.title=incoming.title;model.developer=incoming.developer;model.projects=incoming.projects}else{const result=mergePortfolioImport(model.projects,incoming.projects,strategy);model.projects=result.projects;const {added,replaced,skipped,copied}=result.stats;const summary=`Импорт завершён: добавлено ${added}, обновлено ${replaced}, пропущено ${skipped}, копий ${copied}.`;pendingImport=null;model.demo=false;await save();$('#import-dialog').close();toast(summary);return}pendingImport=null;model.demo=false;await save();$('#import-dialog').close();toast(`Импортировано проектов: ${model.projects.length}. Создана резервная копия до замены.`)}
async function removeProjectsWithUndo(ids,message,{closeDetails=false}={}){
  const idSet=new Set(ids.map(Number)),before=model.projects,wasDemo=model.demo,selectionBefore=new Set(selectedProjectIds);
  const removed=before.map((project,index)=>({project:structuredClone(project),index})).filter(item=>idSet.has(item.project.id));
  if(!removed.length)return;
  model.projects=before.filter(project=>!idSet.has(project.id));for(const id of idSet)selectedProjectIds.delete(id);model.demo=false;
  try{await save()}catch(error){model.projects=before;model.demo=wasDemo;selectedProjectIds=selectionBefore;render();toast(`Проекты не удалены: ${error.message}`,true);return}
  if(closeDetails&&$('#detail-dialog').open)$('#detail-dialog').close();
  const undoToast=toast(message,false,{
    label:'Отменить',
    onDismiss:()=>requestAnimationFrame(()=>{if(document.activeElement===document.body||!document.activeElement?.isConnected){const heading=$('#main-content h1')||main;heading.tabIndex=-1;heading.focus({preventScroll:true})}}),
    run:async()=>{
      const collision=removed.find(item=>model.projects.some(project=>project.id===item.project.id));
      if(collision)throw new Error('ID проекта уже занят. Данные не изменены.');
      const afterRemoval=model.projects,wasDemoAfterRemoval=model.demo,selectionAfterRemoval=new Set(selectedProjectIds);
      for(const item of [...removed].sort((a,b)=>a.index-b.index))model.projects.splice(Math.min(item.index,model.projects.length),0,item.project);
      model.demo=wasDemo;for(const item of removed){if(selectionBefore.has(item.project.id))selectedProjectIds.add(item.project.id)}
      try{await save()}catch(error){model.projects=afterRemoval;model.demo=wasDemoAfterRemoval;selectedProjectIds=selectionAfterRemoval;render();throw error}
      $('#search-announcer').textContent=`Восстановлено проектов: ${removed.length}.`;
      const restored=removed.find(item=>document.querySelector(`[data-detail="${item.project.id}"]`));
      document.querySelector(`[data-detail="${restored?.project.id}"]`)?.focus();
      toast(removed.length===1?'Проект восстановлен.':`Восстановлено проектов: ${removed.length}.`);
    },
  });
  undoToast.querySelector('.toast-action')?.focus({preventScroll:true});
}
function action(x){if(x==='new-project')openProject();if(x==='remove-cover'){editingCoverPath='';$('#cover-image-data').value='';$('#cover-file').value='';renderCoverPreview('');scheduleProjectDraftSave()}if(x==='export-json'){download('folio-backup.json',JSON.stringify(serializePortfolio(model),null,2),'application/json');toast('Резервная копия скачана')}if(x==='export-md'){download('portfolio.md',markdownExport(model),'text/markdown;charset=utf-8');toast('Markdown-файл создан')}if(x==='export-csv'){download('projects.csv',csvExport(model),'text/csv;charset=utf-8');toast('CSV-файл создан')}if(x==='preview-static')previewStaticShowcase();if(x==='export-static')exportStaticShowcase();if(x==='import-json'){importDialogOpener=document.activeElement;$('#import-file').click();}if(x==='clear-all'||x==='clear-demo'){if(confirm(x==='clear-all'?'Удалить все проекты?':'Убрать демонстрационные проекты?'))removeProjectsWithUndo(model.projects.map(project=>project.id),'Проекты удалены.')}if(x==='save-filter-view')openSavedFilterDialog();if(x==='delete-filter-view')deleteSavedFilterView();if(x==='install'&&installPrompt){installPrompt.prompt();installPrompt.userChoice.then(r=>{if(r.outcome==='accepted')toast('Приложение устанавливается');installPrompt=null;render()})}}
