$('#import-dialog').addEventListener('close',()=>{pendingImport=null});
$('#showcase-preview-dialog').addEventListener('close',()=>{$('#showcase-preview-frame').srcdoc='';pendingShowcaseHtml='';$('#showcase-export-summary').replaceChildren()});
$('#showcase-export-download').addEventListener('click',()=>{if(!pendingShowcaseHtml){toast('Сначала подготовьте предпросмотр витрины.',true);return}download('folio-showcase.html',pendingShowcaseHtml,'text/html;charset=utf-8');$('#showcase-preview-dialog').close();toast('Автономная витрина скачана — проверьте файл перед публикацией')});
for(const dialog of document.querySelectorAll('dialog'))dialog.addEventListener('close',()=>{const target=dialogOpeners.get(dialog),parent=target?.closest('dialog');if(target?.isConnected&&target.getClientRects().length&&(!parent||parent.open))target.focus();else (main.querySelector('h1')||main).focus()});
main.addEventListener('input',e=>{if(e.target.id==='search-input'){const val=e.target.value,pos=e.target.selectionStart;render();const input=$('#search-input');input.value=val;input.focus();input.setSelectionRange(pos,pos);announceProjectResults()}});main.addEventListener('change',e=>{if(e.target.matches('[data-select-project]'))setProjectSelection(e.target.dataset.selectProject,e.target.checked);else if(e.target.id==='select-visible-projects')selectVisibleProjects(e.target.checked);else if(['filter-type','filter-status','filter-tag','sort-projects','filter-featured'].includes(e.target.id)){render();announceProjectResults()}});
main.addEventListener('submit',async e=>{if(e.target.id!=='profile-form')return;e.preventDefault();const form=e.target,d=Object.fromEntries(new FormData(form)),previous=model.developer;try{model.developer=normalizeDeveloper({...previous,...d,include_email:form.elements.include_email.checked,include_website:form.elements.include_website.checked,include_github:form.elements.include_github.checked});$('#profile-form-error').textContent='';await save();toast('Профиль сохранён локально')}catch(err){model.developer=previous;$('#profile-form-error').textContent=err.message}});
$('#saved-filter-form').addEventListener('submit',e=>{e.preventDefault();persistSavedFilterView()});$('#saved-filter-dialog').addEventListener('close',()=>{pendingFilterView=null});
$('#theme-toggle').addEventListener('click',()=>{const dark=document.documentElement.dataset.theme!=='dark';document.documentElement.dataset.theme=dark?'dark':'light';$('#theme-toggle').setAttribute('aria-pressed',String(dark));localStorage.setItem('folio-theme',dark?'dark':'light')});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();view='projects';render();$('#search-input')?.focus()}});
document.addEventListener('keydown',e=>{
  if(e.key!=='Tab')return;
  const dialog=[...document.querySelectorAll('dialog[open]')].at(-1);
  if(!dialog)return;
  const focusable=[...dialog.querySelectorAll('a[href],button:not([disabled]),input:not([disabled]):not([type="hidden"]),select:not([disabled]),textarea:not([disabled]),[tabindex]:not([tabindex="-1"])')].filter(el=>el.getClientRects().length&&getComputedStyle(el).visibility!=='hidden');
  if(!focusable.length){e.preventDefault();dialog.focus();return}
  const first=focusable[0],last=focusable[focusable.length-1],active=document.activeElement;
  if(!dialog.contains(active)){e.preventDefault();(e.shiftKey?last:first).focus()}
  else if(e.shiftKey&&active===first){e.preventDefault();last.focus()}
  else if(!e.shiftKey&&active===last){e.preventDefault();first.focus()}
},true);
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;render()});window.addEventListener('online',()=>{render();serviceWorkerRegistration?.update().catch(()=>{})});window.addEventListener('offline',render);
const updateNotice=$('#update-notice'),hadServiceWorkerController='serviceWorker'in navigator&&Boolean(navigator.serviceWorker.controller);let serviceWorkerRegistration=null;
function showUpdateNotice(){if(updateNotice)updateNotice.hidden=false}
$('#update-reload')?.addEventListener('click',async e=>{const button=e.currentTarget;button.disabled=true;button.textContent='Сохраняю…';if($('#project-dialog')?.open){scheduleProjectDraftSave();await new Promise(resolve=>setTimeout(resolve,400));await draftWriteQueue.catch(()=>{});if($('#project-draft-status')?.textContent.startsWith('Не удалось сохранить')){button.disabled=false;button.textContent='Перезапустить';toast('Черновик пока не сохранён. Исправьте проблему и попробуйте обновить ещё раз.',true);return}}location.reload()});$('#update-dismiss')?.addEventListener('click',()=>{if(updateNotice)updateNotice.hidden=true});
if('serviceWorker'in navigator)navigator.serviceWorker.addEventListener('controllerchange',()=>{if(hadServiceWorkerController)showUpdateNotice()});
async function start(){try{const saved=await store.get();if(saved){const p=parsePortfolioFile(JSON.stringify(saved));Object.assign(model,{title:p.title,developer:normalizeDeveloper(p.developer),projects:p.projects,demo:saved.demo===true})}else{const p=parsePortfolioFile(await(await fetch('./demo.json')).text());Object.assign(model,{title:p.title,developer:normalizeDeveloper(p.developer),projects:p.projects,demo:true});await store.put({...serializePortfolio(model),demo:true})}const theme=localStorage.getItem('folio-theme');if(theme)document.documentElement.dataset.theme=theme;render()}catch(e){main.innerHTML=`<div class="fatal-state"><h1>Не удалось открыть портфолио</h1><p>${esc(e.message)}</p><button class="button button-quiet" onclick="location.reload()">Повторить</button></div>`}if('serviceWorker'in navigator&&location.protocol!=='file:')try{serviceWorkerRegistration=await navigator.serviceWorker.register('./sw.js')}catch{}}await start();





